function tab(id){$$('.view').forEach(x=>x.classList.toggle('active',x.id===id));$$('nav button').forEach(x=>x.classList.toggle('active',x.dataset.tab===id));if(id==='explore')setTimeout(()=>map?.invalidateSize(),10);if(id==='trip')renderTrip();window.scrollTo({top:0,behavior:'smooth'})}
