function card(p){return `<article class="place"><span class="badge">${symbols[p.category]||'●'} ${esc(p.category)}${p.subcategory?' · '+esc(p.subcategory):''}</span><h3>${esc(p.name)}</h3><button class="save" data-save="${p.id}" aria-label="${saved.includes(p.id)?'Remove':'Save'} ${esc(p.name)}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'♥':'♡'}</button><p>${esc(p.description)}</p><button class="show" data-place="${p.id}">Read details ↗</button><a href="${p.source}" target="_blank" rel="noopener">Official details</a></article>`}
function bindCards(el){el.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>save(+b.dataset.save));el.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>showPlace(+b.dataset.place))}
function showPlace(id){const p=places.find(p=>p.id===id);tab('explore');if(!map)return;showPlaceDetails(p);if(!p.mapped){map.closePopup();return}map.setView([p.lat,p.lng],14);if(innerWidth<650)$('#map').scrollIntoView({behavior:'smooth',block:'center'})}
