function renderTrip(){$('#tripPlaces').innerHTML=places.filter(p=>saved.includes(p.id)).map(card).join('')||'<p class="empty">Your trip starts with a favourite.<br>Tap a heart on any place to save it here.</p>';bindCards($('#tripPlaces'))}
