 $('#featurePanel').hidden=false;$('#featureTitle').textContent=p.name;
 const position=p.mapped?'<div class="attribute"><b>Source-backed reference position</b>'+formatUTM(p.lat,p.lng)+'</div><a href="'+esc(p.coordinateSource)+'" target="_blank" rel="noopener">Coordinate source ↗</a>':'<p><b>Map pin withheld pending location verification.</b></p>';
