let measuring=false;
function setupGisControls(){
 $('#zoomIn').onclick=()=>map.zoomIn();$('#zoomOut').onclick=()=>map.zoomOut();
 let points=[],line=L.polyline([],{color:'#007ac2',weight:3,dashArray:'6 4'}).addTo(map),dots=L.layerGroup().addTo(map);
 const formatDistance=m=>m>=1000?(m/1000).toFixed(2)+' km':Math.round(m)+' m';
 function redraw(){line.setLatLngs(points);dots.clearLayers();points.forEach(p=>L.circleMarker(p,{radius:4,color:'#fff',weight:2,fillColor:'#007ac2',fillOpacity:1,interactive:false}).addTo(dots));let total=0;for(let i=1;i<points.length;i++)total+=map.distance(points[i-1],points[i]);$('#measurement').textContent=points.length>1?'Distance: '+formatDistance(total)+' · '+(points.length-1)+' segments · click to extend':'Click the map to add measurement points. Straight-line distance, not driving distance.';$('#measurement').hidden=!measuring&&!points.length;$('#clearMeasure').hidden=!points.length;}
 $('#measure').onclick=()=>{measuring=!measuring;$('#measure').setAttribute('aria-pressed',measuring);$('#map').classList.toggle('measuring',measuring);$('#measure').textContent=measuring?'Finish measure':'Measure';redraw()};
 $('#clearMeasure').onclick=()=>{points=[];redraw()};
 map.on('click',e=>{if(measuring){points.push(e.latlng);redraw()}});
}
